-- Rollback-only. No provider calls, credentials, new Auth accounts or retained test records.
begin;
create temp table ig_checks(name text,passed boolean);
create function pg_temp.check_it(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;insert into ig_checks values(label,true);end$$;
do $$
declare uid uuid;sid uuid;claims jsonb;p jsonb;j jsonb;lease jsonb;cfg int;root text=repeat('a',64);saved jsonb;content public.ig_content;
begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where lower(u.email)='akm@indiagully.com' order by s.created_at desc limit 1;
 if sid is null then raise exception 'Existing owner session required';end if;
 claims=jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated');perform set_config('request.jwt.claims',claims::text,true);
 select version into cfg from ig_private.integration_config where id='runway';
 p=jsonb_build_object('provider','runway','kind','image','practice','real-estate','request_id',gen_random_uuid(),'config_version',cfg,'input',jsonb_build_object('kind','image','prompt','SYSTEM TEST abstract illustrative editorial creative','ratio','1280:720','duration',0,'public_approved',true,'estimated_credits',5));
 begin perform public.ig_provider_prepare(p);raise exception 'Disabled accepted';exception when raise_exception then if sqlerrm<>'Provider is disabled' then raise;end if;end;
 perform pg_temp.check_it(true,'Disabled provider cannot create jobs');
 update ig_private.integration_config set mode='enabled' where id='runway';
 perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);
 begin perform public.ig_provider_prepare(p);raise exception 'MFA bypass';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'MFA enforced before generation');perform set_config('request.jwt.claims',claims::text,true);
 update public.ig_profiles set roles=array['editor'],practice_grants='{"hospitality":["read","write"]}' where id=uid;
 begin perform public.ig_provider_prepare(p);raise exception 'Cross practice';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'Practice scope enforced');
 update public.ig_profiles set roles=array['client'],practice_grants='{}' where id=uid;
 begin perform public.ig_provider_prepare(p);raise exception 'Client generate';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'Clients cannot generate staff creatives');
 update public.ig_profiles set roles=array['owner'],practice_grants='{}' where id=uid;
 j=public.ig_provider_prepare(p);
 perform pg_temp.check_it(public.ig_provider_prepare(p)->>'id'=j->>'id','Identical request is idempotent');
 begin perform public.ig_provider_prepare(jsonb_set(p,'{input,prompt}','"A different approved illustrative creative brief"'));raise exception 'Changed intent accepted';exception when raise_exception then if sqlerrm<>'Request reference already used for different input' then raise;end if;end;
 perform pg_temp.check_it(true,'Reused request ID cannot change generation intent');
 update public.ig_provider_jobs set created_at=now()-interval '1 minute' where id=(j->>'id')::uuid;
 update ig_private.integration_config set settings=settings||'{"daily_credit_limit":5}' where id='runway';
 begin perform public.ig_provider_prepare(p||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'Budget bypass';exception when raise_exception then if sqlerrm<>'Daily creative credit budget reached' then raise;end if;end;
 perform pg_temp.check_it(true,'Credit budget enforced before provider call');
 begin perform public.ig_provider_worker('invalid',jsonb_build_object('action','claim'));raise exception 'Forged worker';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'Worker requires root authorisation');
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(root,'UTF8'),'sha256'),'hex');
 lease=public.ig_provider_worker(root,'{"action":"claim"}');
 perform pg_temp.check_it(lease->>'id'=j->>'id' and lease->>'status'='submitting','Claim reserves one paid submission');
 perform pg_temp.check_it(public.ig_provider_worker(root,'{"action":"claim"}') is null,'Leased submission cannot be claimed twice');
 update public.ig_provider_jobs set lease_until=now()-interval '1 minute' where id=(j->>'id')::uuid;
 perform public.ig_provider_worker(root,'{"action":"claim"}');
 perform pg_temp.check_it(exists(select 1 from public.ig_provider_jobs where id=(j->>'id')::uuid and status='unknown'),'Interrupted submission becomes unknown without automatic retry');
 update public.ig_provider_jobs set status='pending',provider_id=gen_random_uuid()::text,next_check_at=null,lease_until=null where id=(j->>'id')::uuid;
 lease=public.ig_provider_worker(root,'{"action":"claim"}');
 perform public.ig_provider_worker(root,jsonb_build_object('action','finish','id',j->>'id','lease_token',lease->>'lease_token','status','pending','source_url','https://dnznrvs05pmza.cloudfront.net/system-test.png'));
 perform public.ig_provider_worker(root,jsonb_build_object('action','stored','id',j->>'id','asset_key',(j->>'id')||'.png','mime','image/png'));
 perform pg_temp.check_it(public.ig_provider_worker(root,jsonb_build_object('action','asset','id',j->>'id','public',true)) is null,'Stored media remains private');
 begin perform public.ig_provider_manage(jsonb_build_object('action','publish','id',j->>'id','reviewed',false));raise exception 'Review bypass';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'Public creative release requires explicit review');
 perform public.ig_provider_manage(jsonb_build_object('action','publish','id',j->>'id','reviewed',true));
 perform pg_temp.check_it(public.ig_provider_worker(root,jsonb_build_object('action','asset','id',j->>'id','public',true))->>'id'=j->>'id','Reviewed image can be served publicly');
 begin perform public.ig_save_content(jsonb_build_object('kind','article','practice','real-estate','title','SYSTEM TEST creative','slug','system-test-creative','public_data',jsonb_build_object('image','/images/generated/'||(j->>'id')||'.png','image_alt','Actual property photograph')));raise exception 'Unlabelled image accepted';exception when raise_exception then if sqlerrm<>'Use the generated or enhanced image disclosure' then raise;end if;end;
 perform pg_temp.check_it(true,'Generated content must be labelled illustrative');
 perform public.ig_provider_manage(jsonb_build_object('action','withdraw','id',j->>'id'));
 perform pg_temp.check_it(public.ig_provider_worker(root,jsonb_build_object('action','asset','id',j->>'id','public',true)) is null,'Withdrawal removes public media access');
 update ig_private.integration_config set settings=settings||'{"daily_credit_limit":120}' where id='runway';
 j=public.ig_provider_prepare(p||jsonb_build_object('request_id',gen_random_uuid()));
 perform public.ig_provider_manage(jsonb_build_object('action','cancel','id',j->>'id'));
 perform pg_temp.check_it(exists(select 1 from public.ig_provider_jobs where id=(j->>'id')::uuid and status='cancelled'),'Queued job cancellation prevents submission');
 select * into content from public.ig_content where kind='opportunity' and status='published' limit 1;
 perform public.ig_content_action(jsonb_build_object('action','archive','id',content.id,'version',content.version));
 perform pg_temp.check_it(not exists(select 1 from public.ig_public_content where id=content.id),'Archiving a database listing immediately removes its public record');
 perform pg_temp.check_it(exists(select 1 from public.ig_content where id=content.id and status='archived'),'Archived listing remains in CMS for restoration');

 update ig_private.integration_config set mode='enabled',settings=settings||'{"dlt_approved":true,"message_id":"12345","template_text":"Your report {#var#} is ready.","daily_request_limit":1}' where id='fast2sms';
 select version into cfg from ig_private.integration_config where id='fast2sms';
 p=jsonb_build_object('provider','fast2sms','kind','sms','practice','horeca','request_id',gen_random_uuid(),'config_version',cfg,'input',jsonb_build_object('phone','8988988988','variables',jsonb_build_array('SYSTEM TEST'),'service_confirmed',true,'consent_reference','Rollback-only service permission fixture'));
 update public.ig_profiles set roles=array['editor'],practice_grants='{"horeca":["read","write"]}' where id=uid;
 begin perform public.ig_provider_prepare(p);raise exception 'Staff SMS bypass';exception when insufficient_privilege then null;end;
 perform pg_temp.check_it(true,'Service SMS queue is owner-only');
 update public.ig_profiles set roles=array['owner'],practice_grants='{}' where id=uid;
 j=public.ig_provider_prepare(p);lease=public.ig_provider_worker(root,'{"action":"claim"}');
 perform public.ig_provider_worker(root,jsonb_build_object('action','finish','id',j->>'id','lease_token',lease->>'lease_token','status','accepted','provider_id','controlled-response-only'));
 perform pg_temp.check_it(exists(select 1 from public.ig_provider_jobs where id=(j->>'id')::uuid and status='accepted'),'SMS acknowledgement records acceptance, not delivery');
 begin perform public.ig_provider_prepare(p||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'SMS daily cap bypass';exception when raise_exception then if sqlerrm<>'Daily provider request limit reached' then raise;end if;end;
 perform pg_temp.check_it(true,'Daily SMS request cap enforced');
end$$;
select * from ig_checks;
rollback;
